const x=$json;
const ops=['cart_view','cart_add','cart_remove','cart_update','cart_clear'];
if(!ops.includes(x.operation)) throw new Error('Invalid cart operation');
if(!x.request_id || !x.conversation_id || !x.customer_id) throw new Error('Missing cart identity');
if(!['sales','cart_validation','checkout_validation'].includes(x.caller_context?.purpose)) throw new Error('Invalid caller purpose');

const itemOps=['cart_add','cart_remove','cart_update'];
if(itemOps.includes(x.operation) && (!x.product_id || (x.quantity===undefined && x.operation!=='cart_remove'))) {
  throw new Error('Missing product/quantity');
}
if(x.quantity!==undefined && (!Number.isInteger(Number(x.quantity)) || Number(x.quantity)<0 || Number(x.quantity)>99)) {
  throw new Error('Invalid quantity');
}
return [{json:{
  request_id:String(x.request_id),
  conversation_id:String(x.conversation_id),
  customer_id:String(x.customer_id),
  operation:x.operation,
  caller_context:x.caller_context,
  product_id:x.product_id ?? null,
  variation_id:x.variation_id ?? null,
  quantity:x.quantity===undefined?null:Number(x.quantity),
  cart:x.cart ?? null,
  idempotency_key:x.idempotency_key ?? `${x.customer_id}:${x.conversation_id}:${x.operation}:${x.product_id??'cart'}:${x.quantity??''}`
}}];

const x=$json;
const readOnly=x.operation==='cart_view';
const mutation=x.operation!=='cart_view';
return [{json:{
 ...x,
 authorization_required:mutation,
 live_product_validation:true,
 stale_cart_check:true,
 execution_mode:readOnly?'read':'validated_mutation'
}}];

const x=$json;
if(x.authorization_required && x.caller_context?.authorized !== true) {
  return [{json:{...x,rejected:true,rejection_reason:'cart_mutation_not_authorized'}}];
}
return [{json:{...x,rejected:false}}];

return [{json:{
 success:false,
 request_id:$json.request_id,
 operation:$json.operation,
 error_code:$json.rejection_reason,
 execution_allowed:false
}}];

const x=$json;
// WF-12 deliberately delegates live product/stock validation to WF-11
// and persistence/execution to WF-20. This node creates the bounded contract.
let gateway_operation='cart_view';
if(x.operation==='cart_add') gateway_operation='cart_add';
if(x.operation==='cart_remove') gateway_operation='cart_remove';
if(x.operation==='cart_update') gateway_operation='cart_update';
if(x.operation==='cart_clear') gateway_operation='cart_clear';

return [{json:{...x,gateway_operation}}];

const r=$json;
if(r.error || r.success===false) {
  return [{json:{
    success:false,
    request_id:$node['Validate Cart Contract'].json.request_id,
    operation:$node['Validate Cart Contract'].json.operation,
    error_code:r.error_code || 'cart_execution_failed',
    execution_allowed:false
  }}];
}
const cleanCart=r.cart || r.data?.cart || null;
return [{json:{
 success:true,
 request_id:$node['Validate Cart Contract'].json.request_id,
 conversation_id:$node['Validate Cart Contract'].json.conversation_id,
 customer_id:$node['Validate Cart Contract'].json.customer_id,
 operation:$node['Validate Cart Contract'].json.operation,
 cart:cleanCart,
 source:'woocommerce',
 verified_at:new Date().toISOString(),
 execution_allowed:$node['Validate Cart Contract'].json.authorization_required ? true : false
}}];
